/* Help is independent of experiment state: opening it never pauses the worker. */
(()=>{const byId=id=>document.getElementById(id),dialog=byId('aboutDialog'),opener=byId('aboutButton'),article=byId('guideArticle'),search=byId('guideSearch'),nav=byId('guideNav'),jump=byId('guideJump'),sections=Array.from(article.querySelectorAll('[data-guide-title]'));let previousFocus=null,previousOverflow='',links=[];const behavior=()=>typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
function setCurrent(id){for(let {section,link} of links){if(section.id===id)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current')}jump.value=id}
function go(id){let section=sections.find(s=>s.id===id&&!s.hidden);if(!section)return;article.scrollTo({top:Math.max(0,section.offsetTop-18),behavior:behavior()});setCurrent(id)}
for(let section of sections){let link=document.createElement('a');link.href='#'+section.id;link.textContent=section.dataset.guideTitle;link.onclick=e=>{e.preventDefault();go(section.id)};nav.append(link);let option=document.createElement('option');option.value=section.id;option.textContent=section.dataset.guideTitle;jump.append(option);links.push({section,link,option})}
function filter(){let query=search.value.trim().toLocaleLowerCase(),count=0;for(let {section,link,option} of links){let visible=!query||section.textContent.toLocaleLowerCase().includes(query);section.hidden=!visible;link.hidden=!visible;option.hidden=!visible;option.disabled=!visible;if(visible)count++}byId('guideNoResults').hidden=count!==0;byId('guideSearchStatus').textContent=query?count+' of '+sections.length+' sections match':sections.length+' guide sections';jump.disabled=count===0;article.scrollTop=0;const first=sections.find(s=>!s.hidden);if(first)setCurrent(first.id)}
function openGuide(){if(dialog.open)return;previousFocus=document.activeElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.showModal();opener.setAttribute('aria-expanded','true');filter();search.focus();search.select()}
function closed(){document.body.style.overflow=previousOverflow;opener.setAttribute('aria-expanded','false');if(previousFocus&&typeof previousFocus.focus==='function')previousFocus.focus();else opener.focus()}
opener.onclick=openGuide;byId('aboutClose').onclick=()=>dialog.close();dialog.addEventListener('close',closed);dialog.addEventListener('click',e=>{if(e.target!==dialog)return;let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});search.oninput=filter;jump.onchange=()=>go(jump.value);byId('guideBackTop').onclick=()=>{article.scrollTo({top:0,behavior:behavior()});let first=sections.find(s=>!s.hidden);if(first)setCurrent(first.id)};article.addEventListener('scroll',()=>{let current=sections.filter(s=>!s.hidden).findLast(s=>s.offsetTop<=article.scrollTop+60)||sections.find(s=>!s.hidden);if(current)setCurrent(current.id)},{passive:true});document.addEventListener('keydown',e=>{let target=e.target;if(e.key!=='?'||e.ctrlKey||e.altKey||e.metaKey||target?.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(target?.tagName||''))return;e.preventDefault();openGuide()});filter();})();
